// 2) Attribute routing on a controller
[Route("api/v{version:apiVersion}/orders")]
[ApiController]
public class OrdersController : ControllerBase
{
    [HttpGet("{id:guid}")]                       // constraint filters matches
    public ActionResult<Order> Get(Guid id) => Ok();

    [HttpGet("search")]
    public ActionResult Search([FromQuery] string? q) => Ok();
}

// 3) Minimal API — everything inline, binding by convention
app.MapGet("/todos/{id:int}", async (int id, TodoDb db, CancellationToken ct) =>
        await db.Todos.FindAsync(new object[] { id }, ct) is { } todo
            ? Results.Ok(todo)
            : Results.NotFound())
    .WithName("GetTodo")                         // link generation + OpenAPI id
    .RequireAuthorization("CanReadTodos")         // policy metadata
    .WithOpenApi();

app.MapPost("/todos", async (CreateTodo dto, TodoDb db) => { /* dto from body */ });
app.MapGet("/health/ready", (HttpContext ctx) => Results.Ok())
    .ExcludeFromDescription();

// Route constraint alternatives to manual parsing:
// /todos/{id:int}      → "abc" gives 404, not a FormatException in your code
// /files/{**path}      → catch-all for nested paths
// /tags/{slug:regex(^[[a-z0-9-]]+$)} → pattern enforcement at match time
